ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["scenes_any_11"] = {
{"s11_a06_dont_say_why_022","any",2,"reg=civilian,rescue|tmp=seasoned|day=40,400|mood=grim",{1,"Put it out on nineteen, say what we need and say what we'll pay for it",2,"That tells everybody with a rifle we got a sick woman and something to pay with",1,"Yeah, then write it careful - ask for a doctor and don't say why"}},
{"s11_a06_old_and_armed_023","any",2,"reg=worker,civilian|tmp=seasoned|day=40,300|mood=calm",{1,"They'll trade a bushel for a day's work on their fence",2,"A whole day for one bushel?",1,"And they feed you dinner while you work, them brothers ain't thieves - just old and armed"}},
{"s11_a06_somebody_said_amen_024","any",3,"reg=rescue,civilian|tmp=seasoned|day=60,400|mood=warm|world=snow",{1,"He said Sunday it'd all break by the first frost",2,"It didn't break",1,"No, and Wednesday he stood up in front of everybody and said he'd been wrong",3,"How'd folks take that?",1,"Quiet, then somebody said amen, and honest, that's the best minute we've had here"}},
{"s11_a06_my_own_name_on_the_end_025","any",4,"reg=civilian,family|tmp=seasoned|day=40,400|hour=16,5|mood=grim",{1,"Somebody's got to go on the air tonight and say what happened at that bridge",2,"Say it how?",3,"Say it true, all of it - including the part where we walked off and left her there",4,"Say it true and every bunch in this county knows we walked off",1,"Then I'll say it true and slow, and I'll put my own name on the end of it"}},
{"s11_a06_nobody_to_be_his_doctor_026","any",2,"reg=rescue,civilian|tmp=seasoned|day=40,400|mood=grim",{1,"He's running a fever and he won't let anybody look at him",2,"Won't let who look at him? He's the who",1,"That's the joke of it, ain't it, man's got nobody to be his doctor"}},
{"s11_a06_same_squeak_027","any",2,"reg=civilian,family|tmp=seasoned|day=80,400|mood=sad|world=door,building",{1,"I dreamed about that gate again",2,"The gate",1,"It don't even sound like a gate in the dream - sounds like the pantry door - same squeak"}},
{"s11_a06_shes_wearing_it_right_now_028","any",2,"reg=family,civilian|tmp=seasoned|day=60,400|mood=warm",{1,"So we dug the coat back up, took about an hour with two shovels",2,"And?",1,"And Darlene asked could she keep it, so she's got it, she's wearing it right now"}},
{"s11_a06_just_stand_there_029","any",3,"reg=family,civilian|tmp=seasoned|day=30,400|mood=sad",{1,"His wife wants to be out there when it's done",2,"You can't let her be out there",1,"I can't stop her, either, she's his wife, she's got more right to it than I have",3,"Then stand in front of her, just stand there and don't move"}},
{"s11_a06_somebody_sat_outside_with_a_lamp_030","any",4,"reg=civilian,rescue|tmp=seasoned|day=30,400|mood=grim|world=door,building,water,road",{1,"Two of 'em, bit inside an hour of each other out on the creek road",2,"So it's the same clock twice",3,"Or one of 'em's a scratch, and a scratch ain't always it - you don't know that",4,"You want to keep a man overnight on a maybe with children under that roof",1,"Barn, both in the barn, door barred, somebody sat outside it all night with a lamp"}},
{"s11_a06_instead_of_sending_a_kid_031","any",2,"reg=rescue,civilian|tmp=seasoned|day=40,400|mood=calm",{1,"He don't charge for it, that's the thing folks forget about him",2,"So what does he want?",1,"To be asked - every time, wants somebody to come ask him instead of sending a kid"}},
{"s11_a06_it_aint_about_god_032","any",2,"reg=rescue|tmp=seasoned|day=40,400|mood=grim",{1,"Half that church won't sit in a pew with him",2,"And the other half?",1,"The other half's been stitched by him, that's the split, plain as that, it ain't about God at all"}},
{"s11_a06_walnuts_and_a_hatchet_033","any",2,"reg=civilian,family|tmp=seasoned|day=60,400|mood=warm",{1,"We fed that family in October and never laid eyes on 'em again",2,"Until?",1,"Until Sunday, two sacks of walnuts and a hatchet on the gate post - no note on it"}},
{"s11_a06_you_do_that_arithmetic_034","any",2,"reg=rescue,family|tmp=seasoned|day=60,400|mood=calm",{1,"He's teaching the Cobb girl, says she's got the hands for it",2,"She's seventeen years old",1,"Seventeen and steady, he's fifty-eight with a cough - you do that arithmetic"}},
{"s11_a06_take_your_hat_off_and_ask_035","any",4,"reg=family,rescue|tmp=seasoned|day=40,400|mood=fear",{1,"Baby's turned sideways and Nell's been at it eleven hours",2,"Where's the midwife at?",3,"She's in there, says she needs the doctor, and she's asking for him by name",4,"Then go ask him - ask him proper - take your hat off and ask him",1,"I'll go, I'll say please - I got nothing else to trade him but that"}},
{"s11_a06_which_they_hate_worse_036","any",2,"reg=rescue|tmp=seasoned|day=60,400|mood=grim",{1,"Folks keep asking me was it wrong, letting them nine in",2,"What do you tell 'em?",1,"I say I don't know, which they hate, then I say I'd do it again, which they hate worse"}},
{"s11_a06_still_reads_em_all_037","any",2,"reg=civilian,rescue|tmp=seasoned|day=40,400|mood=sad",{1,"He reads the names out every night at nine, anybody looking for anybody",2,"That ever work?",1,"Twice, twice out of four hundred names, and he still reads 'em all every night"}},
{"s11_a06_so_we_know_and_thats_all_038","any",2,"reg=civilian,family|tmp=seasoned|day=40,400|mood=sad|world=trees",{1,"We buried him under the pear tree and we never put a thing on it",2,"Why not?",1,"A marker tells a stranger there's a house here, and we know where he is anyway"}},
{"s11_a06_somebody_thatll_plant_it_again_039","any",3,"reg=worker,civilian|tmp=seasoned|day=80,400|mood=sad",{1,"Both them brothers are dead, older one first, younger about a week behind him",2,"And the garden?",1,"Standing, corn's still stood up in there and nobody's laid a hand on it",3,"Nobody?",1,"Nobody yet - somebody will, I'd like it to be somebody that'll plant it again"}},
{"s11_a06_over_a_rusty_nail_040","any",2,"reg=civilian,rescue|tmp=seasoned|day=30,400|mood=grim|world=fence",{1,"It was a scratch off a nail, a nail in the fence post",2,"You're sure of that",1,"Four days and he's fine, we near about did something to a man over a rusty nail"}},
{"s11_a06_tell_me_the_words_041","any",4,"reg=family|tmp=seasoned|day=60,400|hour=16,5|mood=sad",{1,"Bug asked me where Orbry went and I said he went to Riverside",2,"That's a lie",3,"That's a lie that gets a nine year old through a winter",4,"It's a lie she'll find out on, and then it ain't Orbry she'll be crying over",1,"Then tell me the words, the real ones, for a nine year old, I'll say 'em tonight"}},
{"s11_a06_holding_a_cup_with_two_hands_042","any",2,"reg=rescue,civilian|tmp=seasoned|day=60,400|mood=sad",{1,"He's got a tremor now - left hand",2,"Does he know it?",1,"He knows, been holding his cup with two hands a month so nobody'd see"}},
{"s11_a06_dont_know_yet_which_043","any",2,"reg=civilian,family|tmp=seasoned|day=60,400|mood=grim",{1,"We had one of 'em down in the yard and Loretta said let him walk",2,"And you did?",1,"We did, I'm either going to be proud of that or dead over it - don't know yet which"}},
{"s11_a06_writes_in_it_the_slowest_044","any",2,"reg=civilian,family|tmp=seasoned|day=80,400|mood=sad",{1,"Ada's got three books now, food, findings, and the dead",2,"Three books",1,"And the dead one's the thinnest, and she writes in that one the slowest"}},
{"s11_a06_he_aint_said_no_again_045","any",4,"reg=civilian,rescue|tmp=seasoned|day=40,400|mood=grim",{1,"He asked the doctor to do it, not one of us - the doctor",2,"That ain't a doctor's job",3,"Says he trusts him - don't want a friend doing it, he wants a professional",4,"And what'd the doctor say to that?",1,"Said no, then he sat down out there, and he's still sat there, and he ain't said it again"}},
{"s11_a06_she_said_a_barn_046","any",2,"reg=family,civilian|tmp=seasoned|day=60,400|mood=fear",{1,"Where was she, though - three months - where",2,"She said a barn",1,"Whose barn, how'd she eat, who kept her, she said a barn and then she looked at me"}},
{"s11_a06_one_of_four_047","any",2,"reg=rescue,civilian|tmp=seasoned|day=60,400|mood=sad",{1,"He held a service for Delbert, out in the side yard - read the whole thing through",2,"For Delbert?",1,"Four people come, I was one of 'em, and I ain't proud of being one of four"}},
{"s11_a06_not_one_word_to_nobody_048","any",3,"reg=family,civilian|tmp=seasoned|day=60,400|mood=warm|world=building",{1,"Nell's boy is fine, Nell's fine, and the doctor's asleep on the porch steps",2,"Then let him sleep",1,"Somebody put a quilt over him and won't say who - it was the Pruitt girl's daddy",3,"Him?",1,"Him - don't say nothing about it, not one word to nobody, ever"}},
{"s11_a06_fence_and_supper_049","any",2,"reg=civilian,family|tmp=seasoned|day=200,400|mood=grim|world=fence,road",{1,"Year ago Sunday we put a man out on that road",2,"I know what Sunday it is",1,"We ain't going to say anything about it, are we",2,"No, we're going to do the fence and eat supper, that's what we're going to do"}},
{"s11_a06_give_it_to_whoever_groans_050","any",2,"reg=civilian,worker|tmp=seasoned|day=60,400|mood=funny",{1,"I'm done with it, somebody else can have the microphone",2,"Nobody wants it",1,"Somebody will want it, and that's the one you don't give it to - give it to whoever groans"}},
{"s11_a06_write_it_on_top_051","any",4,"reg=civilian,family|tmp=seasoned|day=80,400|mood=calm",{1,"We got rules for everything and not one line about what this place is for",2,"For staying alive, I'd say",3,"Every place is for staying alive, even the bad ones - that ain't it",4,"Then say it, one sentence, and don't turn it into a sermon",1,"Kids grow up here and the old ones die in a bed - write that on the top of the page"}},
{"s11_a06_go_on_to_bed_052","any",3,"reg=civilian,family|tmp=seasoned|day=100,400|mood=warm",{1,"Corn's in - doctor's asleep, nobody's at the gate",2,"Don't say it out loud",1,"I'm saying it out loud, it was a good day and I want somebody besides me to know it",3,"Alright, it was a good day",1,"Thank you - go on to bed"}},
{"s11_a07_next_week_be_awake_001","any",2,"reg=civilian,worker|tmp=seasoned|day=60,400|mood=funny",{1,"Board's up, names down the left, jobs down the right - it changes Sunday",2,"Who decided I'm on the wash?",1,"Everybody did, Sunday, while you was asleep in the hayloft - next week be awake"}},
{"s11_a07_say_it_back_and_hear_it_002","any",2,"reg=family,civilian|tmp=seasoned|day=60,400|mood=warm",{1,"Odessa used to give the kids reading and figures two hours a morning",2,"Short of hands and she was teaching school?",1,"Short of hands and she was teaching school. Say it back and hear what you're complaining about"}},
{"s11_a07_theres_going_to_be_a_cake_003","any",3,"reg=family,civilian|tmp=seasoned|day=80,400|mood=warm|world=building",{1,"Nolan and the Crites girl want to get married",2,"Married by who?",1,"Brother Stiles - Saturday, they want everybody there and they want a cake",3,"There's always a cake in these plans",1,"There's going to be a cake, I decided that before I ever walked in this room"}},
{"s11_a07_first_middle_and_last_004","any",2,"reg=civilian,rescue|tmp=seasoned|day=40,400|mood=grim",{1,"Anybody dies, they go in the ground inside a day and somebody says their name out loud",2,"Their whole name?",1,"First, middle and last, takes two seconds, costs nothing, and it's what we've got"}},
{"s11_a07_it_sounds_bad_005","any",2,"reg=civilian,family|tmp=seasoned|day=200,400|mood=grim",{1,"This is the second one",2,"Second what",1,"Second winter - that's all, said it out loud to hear it and it sounds bad"}},
{"s11_a07_go_line_by_line_006","any",4,"reg=civilian,family|tmp=seasoned|day=80,400|mood=calm",{1,"The Whitis bunch wants to come in with us, eleven of 'em, counting the baby",2,"Eleven and fourteen's twenty-five mouths",3,"Eleven and fourteen's also two wells, two gardens and twice the watch",4,"And whose rules? Nobody's asking it, so I'm asking it",1,"Ours, and theirs where theirs are better - write both lists and we'll go line by line"}},
{"s11_a07_out_of_god_knows_what_007","any",2,"reg=civilian,family|tmp=seasoned|day=60,400|mood=warm",{1,"It's your thirty days today",2,"I know what day it is",1,"So you sign the book, you get a key, and Dovie's baked something out of God knows what"}},
{"s11_a07_dont_argue_with_him_008","any",3,"reg=civilian,family|tmp=seasoned|day=80,400|mood=warm",{1,"Weldon's going to Riverside to look for his sister",2,"By himself?",1,"By himself, he gets the good boots and the hatchet - he's leaving us his rifle",3,"He don't have to do that",1,"He knows he don't, that's why he's doing it - don't argue with him about it"}},
{"s11_a07_that_was_a_good_rule_009","any",2,"reg=civilian,family|tmp=seasoned|day=100,400|mood=sad|world=trees",{1,"Six now, under the pear tree",2,"Six",1,"And I know every one of their middle names, 'cause we say 'em - that was a good rule"}},
{"s11_a07_five_minutes_after_bubbles_010","any",2,"reg=rescue,worker|tmp=seasoned|day=30,400|mood=calm",{1,"Boil it five full minutes, not till it bubbles, five minutes after it bubbles",2,"That's a pile of wood",1,"It's a pile of wood, cheaper than the whole house down with the runs for a week"}},
{"s11_a07_do_the_swap_011","any",2,"reg=worker|tmp=seasoned|day=80,400|mood=calm|world=building,winter",{1,"That north side of the roof is going to let go this winter",2,"We've got no shingles and no way to get shingles",1,"We've got a barn with tin on it and nothing under it - do the swap"}},
{"s11_a07_thats_the_actual_fight_012","any",2,"reg=family|tmp=seasoned|day=60,400|mood=sad",{1,"Wesley and the Cobb boy went at each other over a bicycle",2,"Whose bicycle?",1,"Neither one's, it's a dead man's bicycle and they both know it - that's the actual fight"}},
{"s11_a07_keeping_four_trading_three_013","any",2,"reg=family,worker|tmp=seasoned|day=80,400|mood=warm|world=fence",{1,"Sadie had seven pups in the feed room",2,"Seven more mouths",1,"Seven dogs that bark before a thing gets near the fence - we keep four, we trade three"}},
{"s11_a07_when_im_the_one_bleeding_014","any",2,"reg=rescue,family|tmp=seasoned|day=40,400|mood=calm",{1,"Every one of y'all learns to pack a wound - everybody, the kids too",2,"The kids?",1,"Especially them, they'll be the ones stood there when I'm the one bleeding"}},
{"s11_a07_everybodys_feet_are_coming_apart_015","any",4,"reg=civilian,family|tmp=seasoned|day=60,400|mood=grim|world=fence",{1,"Two old folks at the fence, he's on a stick and she's near blind",2,"Neither one of 'em can work",3,"She can sit with the babies, that's work, and it frees a woman up for the garden",4,"And him?",1,"Says he was a cobbler, forty years of it, everybody's feet here are coming apart"}},
{"s11_a07_so_nobody_gets_forgot_016","any",2,"reg=civilian,family|tmp=seasoned|day=80,400|mood=warm",{1,"Ada's got a page in that book with everybody's birthday on it",2,"What in the world for?",1,"So nobody gets forgot, she writes 'em down off whatever folks remember, that's all it is"}},
{"s11_a07_nobody_says_the_word_july_017","any",3,"reg=civilian,family|tmp=seasoned|day=300,400|mood=grim",{1,"It's the fourth Sunday",2,"I know what Sunday it is",1,"So do we do something or do we not, I'd like somebody to tell me which",3,"We eat outside and nobody says the word July"}},
{"s11_a07_how_you_know_its_real_018","any",2,"reg=civilian,family|tmp=seasoned|day=150,400|mood=grim",{1,"There's talk of heading south when the weather breaks",2,"Who's talking?",1,"Four people, not the loud ones, either - the quiet ones, that's how you know it's real"}},
{"s11_a07_a_thing_to_feel_sorry_for_019","any",2,"reg=worker,civilian|tmp=seasoned|day=40,400|mood=angry",{1,"Put me on something - anything, I've sat in that chair four days now",2,"You've got a broke arm",1,"Then put me on the beans one-handed, I'm no use as a thing to feel sorry for"}},
{"s11_a07_post_the_chairs_in_sight_020","any",4,"reg=civilian,worker|tmp=seasoned|day=40,400|hour=7,18|mood=calm",{1,"Four on, eight off - three shifts, that's six people tied up every day",2,"Out of thirteen that work, that's near half of us",3,"Then two-man posts at night, one in the daylight",1,"One man alone in daylight is how you lose a man in daylight",4,"So the daylight posts sit where they can see each other - set the chairs in sight"}},
{"s11_a07_we_wave_and_keep_driving_021","any",2,"reg=worker,civilian|tmp=seasoned|day=60,400|mood=calm",{1,"Wickham's is Tuesday, the Ekron folks are the first of the month",2,"And the Zink Road bunch?",1,"The Zink Road bunch we don't trade with, we wave and we keep on driving"}},
{"s11_a07_whole_postal_service_022","any",2,"reg=civilian,family|tmp=seasoned|day=80,400|mood=funny",{1,"Somebody's running letters, boy on a bicycle, twice a month, all over the county",2,"Who pays him?",1,"Everybody feeds him, that's the postal service around here, and it works better than you'd think"}},
{"s11_a07_preach_to_em_anyway_023","any",2,"reg=rescue|tmp=seasoned|day=60,400|mood=funny",{1,"Fourteen come out Sunday, that's more than I had in ninety-two",2,"That ain't a compliment to your preaching",1,"No it ain't, I know exactly what it is, and I'm going to preach to 'em anyway"}},
{"s11_a07_somebodys_going_to_want_it_024","any",2,"reg=family,civilian|tmp=seasoned|day=60,400|mood=calm",{1,"The Cobb boy's got that scanner on every night, writes down everything he hears",2,"He getting anything good?",1,"Mostly nothing, but he's filled a notebook, and one day somebody's going to want it"}},
{"s11_a07_by_the_paper_025","any",3,"reg=civilian,family|tmp=seasoned|day=60,400|mood=funny",{1,"He went out alone, day nine of his thirty",2,"He's out, then. He heard it on his first day",1,"He went out after his dog, and he come back with the dog",3,"After his dog... damn. That does make it harder",1,"Go get Ada. I want this one done by the paper"}},
{"s11_a07_neither_ones_alone_with_it_026","any",4,"reg=civilian,family|tmp=seasoned|day=80,400|mood=calm|world=inside",{1,"Ada's teaching two people to keep the book",2,"Why two?",3,"So when one's sick there's another, and so neither one's ever alone with it",4,"That second part's the real reason and everybody in here knows it",1,"It is, and she said it out loud when she set it up, which I thought was decent"}},
{"s11_a07_get_the_potatoes_out_027","any",2,"reg=worker,family|tmp=seasoned|day=200,400|hour=4,11|mood=warm|world=building",{1,"Ground's working, I put my hand in it this morning and it's ready",2,"It's February",1,"It's the twenty-sixth of February and that ground is ready - get the potatoes out the cellar"}},
{"s11_a07_cant_loot_a_house_for_seed_028","any",2,"reg=worker,family|tmp=seasoned|day=100,400|mood=grim",{1,"Seed, that's what I lay awake on now - not cans - seed",2,"Seed?",1,"You can loot a house for beans, you can't loot a house for next year's seed corn"}},
{"s11_a07_i_didnt_see_it_go_029","any",2,"reg=family|tmp=seasoned|day=200,400|mood=sad",{1,"Bug can't remember what a shopping mall is",2,"She's nine years old",1,"She was seven and she knew, now she don't, and I didn't see it go"}},
{"s11_a07_where_a_stranger_reads_it_030","any",4,"reg=civilian,family|tmp=seasoned|day=100,400|mood=calm|world=road",{1,"Traders keep asking what this place is called, I've been saying the Kelso place",2,"It ain't the Kelso place, no Kelso's been here since before",3,"Call it whatever the road's called and be done",4,"Then it's Tanner, that's a plain name and I like a plain name",1,"Tanner it is, paint it on a board and hang it where a stranger reads it first"}},
{"s11_a07_dont_undo_it_in_one_031","any",2,"reg=civilian,worker|tmp=seasoned|day=150,400|mood=calm",{1,"Everybody carries now, new ones too, after their thirty",2,"That's a change from a year ago",1,"Took us eight months and three arguments to get there - don't undo it in one"}},
{"s11_a07_thats_the_toast_032","any",2,"reg=family,civilian|tmp=seasoned|day=180,400|mood=warm",{1,"Supper's beans and one biscuit apiece",2,"Again",1,"Again, it's the fourteenth of January and every one of us is still here - that's the toast"}},
{"s11_a07_dont_run_youll_scare_em_033","any",2,"reg=rescue,family|tmp=seasoned|day=60,400|mood=warm",{1,"It's a girl and they're both breathing",2,"Both?",1,"Both - go tell the house, and don't run, you'll scare 'em half to death running"}},
{"s11_a07_named_after_nobody_034","any",2,"reg=family,civilian|tmp=seasoned|day=60,400|mood=warm",{1,"They're calling her June",2,"After who?",1,"After nobody, they just liked it - first thing in a year got named after nobody"}},
{"s11_a07_i_got_no_rule_for_quit_035","any",2,"reg=civilian,worker|tmp=seasoned|day=80,400|mood=sad|world=building",{1,"He ain't pulled a shift in eleven days",2,"Is he sick?",1,"He ain't sick, he's sat on that porch and he's quit, I got no rule for quit"}},
{"s11_a07_set_another_chair_out_there_036","any",2,"reg=civilian,family|tmp=seasoned|day=80,400|mood=warm|world=building",{1,"I put Roy out on the porch with him, never said a word - just set another chair out",2,"For how long?",1,"Two days, third morning they both come to breakfast - I ain't asking either one about it"}},
{"s11_a07_without_a_face_on_it_037","any",4,"reg=civilian,family|tmp=seasoned|day=80,400|mood=grim|world=building",{1,"Four rifles in that closet belonged to people that ain't here no more",2,"Then they're the camp's rifles now",3,"Say that to Orbry's wife, go on - say it to her face in them exact words",4,"Ask her - just ask, she might want it out the house worse than you want it in the closet",1,"Then somebody ask her kind, and take her answer without putting a face on it"}},
{"s11_a07_talks_about_it_instead_038","any",2,"reg=civilian,worker|tmp=seasoned|day=60,400|mood=warm",{1,"Fella at Ekron does an hour Thursday nights, weather, who's dead, who's looking",2,"Any music on it?",1,"He talks about music, won't spend the batteries on a record, so he talks about it instead"}},
{"s11_a07_they_know_its_real_039","any",2,"reg=family,worker|tmp=seasoned|day=80,400|mood=warm",{1,"Kids run the water line now, bucket brigade, all four of 'em, twice a day",2,"That's real work for a nine year old",1,"It's real and they know it's real, that's how come they ain't scared all the time"}},
{"s11_a07_gone_before_light_040","any",2,"reg=civilian,family|tmp=seasoned|day=80,400|mood=warm",{1,"That woman come through with the two mules, stayed one night, wouldn't take a bed",2,"Where's she headed?",1,"Wouldn't say, left a sack of sweet corn seed on the table and was gone before light"}},
{"s11_a07_then_everybody_did_041","any",3,"reg=civilian,family|tmp=seasoned|day=200,400|mood=warm",{1,"Ada read the whole year out Sunday, took an hour and ten minutes",2,"The whole year",1,"Every finding, every vote, every name - nobody moved, kids never even fidgeted",3,"What'd folks say after?",1,"Nothing, then somebody clapped, which was strange, and then everybody did"}},
{"s11_a07_we_wanted_the_air_042","any",2,"reg=civilian,family|tmp=seasoned|day=250,400|mood=warm",{1,"That gate stood open all day yesterday",2,"Who left it open?",1,"Nobody left it, we opened it - wasn't nothing out there and we wanted the air"}},
{"s11_a07_write_those_three_043","any",4,"reg=civilian,family|tmp=seasoned|day=200,400|mood=calm|world=trees,snow",{1,"Say we do this again, say it's another one like the last one",2,"Then we do what we did last time",3,"What we did put two people under that tree, and I want it done better",4,"Better how, name it out loud so Ada can write it",1,"Wood cut by September, meat salted by October, nobody out after first snow"}},
{"s11_a07_everything_else_is_just_people_044","any",2,"reg=civilian,worker|tmp=seasoned|day=100,400|mood=calm",{1,"Fella asked me what it takes to live here",2,"So what did he hear from you?",1,"Sign the book, take your turn - say what you took, everything else is just people"}},
{"s11_a07_pass_the_salt_045","any",3,"reg=civilian,family|tmp=seasoned|day=200,400|mood=warm|world=fence",{1,"Y'all remember when we voted on them four at the fence",2,"I remember it",1,"Two of them four are stood out in that garden right this minute",3,"I know it",1,"That's it, that's all I was going to say - pass the salt"}},
{"s12_bell_one_at_a_time_003","any",3,"reg=rescue,family|tmp=fresh,seasoned|hour=22,3|mood=fear",{1,"It rang once at midnight, once at one, once at two",2,"Clockwork bell, some of them old churches had a clock",1,"Cedar Grove never had a clock, that's a rope and a wheel and a pair of hands",3,"Then somebody's sitting in there all night pulling it on the hour",1,"Yeah, I'd rather it was a clock"}},
{"s12_bell_wrong_side_004","any",2,"reg=worker,civilian|tmp=seasoned|hour=20,2|mood=fear",{1,"The bell come from the wrong side of us last night - West",2,"Church is east",1,"Church is east, I'd like to hear your explanation, 'cause I've been working on mine all day"}},
{"s12_bell_after_we_left_005","any",2,"reg=rescue,law|tmp=seasoned|mood=grim|world=door",{1,"We cleared that church Tuesday, wired the doors shut, wrote the date on the board",2,"And it rang Wednesday",1,"Twice Wednesday, doors are still wired - I went and looked at the wire myself"}},
{"s12_bell_calls_them_006","any",2,"reg=civilian,family|tmp=fresh,seasoned|hour=21,3|mood=fear|world=road",{1,"Every time that bell goes, the road fills up, they come from the whole county for it",2,"So somebody's ringing it on purpose",1,"Somebody's ringing it on purpose and they ain't in the church when the road fills up - think on that"}},
{"s12_bell_hymn_no_words_008","any",2,"reg=rescue,family|tmp=seasoned|hour=22,4|mood=fear",{1,"There's singing out that way some nights, no words in it - just the shape of a hymn",2,"Folks holding service",1,"Then they'd sing the words, everybody in this county knows the words"}},
{"s12_bell_bell_answers_009","any",3,"reg=civilian,worker|tmp=seasoned|hour=21,2|mood=fear",{1,"Hoyt rang our dinner bell twice as a joke, back at the bell business",2,"He would",1,"Cedar Grove rang twice back, about a minute later",3,"Come on",1,"He ain't rung it since, he took the clapper out and put it in a drawer"}},
{"s12_bell_knock_no_steps_011","any",2,"reg=civilian,family|tmp=fresh|hour=0,4|mood=fear|world=door",{1,"Three knocks on the trailer door about two, no steps before it, no steps after",2,"You know how a floor tells on a man",1,"That's exactly it, that floor tells on everybody, it didn't tell on that"}},
{"s12_bell_music_in_trees_012","any",2,"reg=civilian,worker|tmp=seasoned|hour=22,3|mood=fear|world=trees,wind",{1,"Something's playing out in them woods, little tinkly thing, like a jewelry box",2,"Wind chimes on somebody's porch",1,"It quits when the wind quits, so you tell me what that means, 'cause I've got nothing"}},
{"s12_bell_stops_when_i_stop_013","any",2,"reg=civilian,worker|tmp=seasoned|hour=21,3|mood=fear",{1,"I quit walking and it quit, I walked, it walked",2,"Echo off the bank",1,"I done it four times to be sure, fourth time I didn't walk, I run"}},
{"s12_bell_boy_from_water_014","any",2,"reg=family|tmp=fresh,seasoned|hour=22,4|mood=fear",{1,"I once thought I heard my boy call from down by the water",2,"Was he there?",1,"Asleep in the tent. Checked him twice. Still remember how sure I was I'd heard him"}},
{"s12_bell_phone_ringing_015","any",2,"reg=civilian,worker|tmp=seasoned|hour=0,5|mood=grim",{1,"Payphone outside the feed store rang last night, rang a long time",2,"Lines are dead, been dead since the eighth",1,"I know the lines are dead, I stood in the lot listening to it ring and I never picked it up"}},
{"s12_bell_dogs_answering_016","any",2,"reg=civilian,family|tmp=seasoned|hour=21,2|mood=fear",{1,"When that bell goes, every dog left in this end of the county answers it",2,"Dogs bark at bells",1,"They don't bark, they set up a howl and then they quit all at once, like somebody said hush"}},
{"s12_bell_siren_test_017","any",3,"reg=law,rescue|tmp=seasoned|hour=11,13|mood=grim",{1,"Town siren went off at noon Saturday, full cycle, up and down, just like a test",2,"Fire board used to run it Saturdays at noon",1,"They did, and the fire board is four men and I have got three of them in the ground",3,"Who's the fourth?",1,"Don't know, that's my whole week now, finding out about the fourth"}},
{"s12_bell_bell_drowned_018","any",2,"reg=worker,civilian|tmp=seasoned|mood=grim",{1,"That bell in Cane Run got took down in seventy nine when the steeple went",2,"So where's it at?",1,"In the ground behind the church, on its side, full of dirt - I helped bury it, I was nineteen",2,"Then that ain't what you're hearing",1,"No sir, that is what I'm hearing"}},
{"s12_bell_wrong_hour_count_019","any",2,"reg=civilian,family|tmp=seasoned|hour=23,5|mood=fear|world=door",{1,"Twelve at two, fourteen at three, I been keeping a tally on the doorframe with a pencil",2,"Going up",1,"One more every night since Sunday, sixteen coming, if it holds, I'll be up for it"}},
{"s12_bell_hymn_at_house_020","any",2,"reg=rescue,family|tmp=fresh,seasoned|hour=21,3|mood=sad",{1,"Brother Stiles rings that bell every evening at six so folks know somebody's still up there",2,"That's a kindness",1,"It was, then it rang Tuesday at six and I buried Brother Stiles on the Monday"}},
{"s12_bell_mower_running_021","any",2,"reg=civilian,worker|tmp=seasoned|hour=19,23|mood=grim",{1,"Somebody's mowing out past the bins, you can hear it of an evening",2,"Good, somebody's keeping their yard",1,"That's a hayfield, Wanda, there ain't a yard within a mile of there"}},
{"s12_bell_ice_cream_truck_022","any",2,"reg=family,civilian|tmp=fresh|hour=19,1|mood=fear|world=vehicle,door,window",{1,"The kids heard the ice cream truck, both of 'em, same time, and they run to the window",2,"You hear it?",1,"I heard it, I stood there while they looked, and I never opened that door"}},
{"s12_bell_radio_repeats_023","any",3,"reg=civilian,worker|tmp=seasoned|hour=0,5|mood=fear",{1,"I said anybody out there on nineteen, nineteen said it back to me",2,"That's your own signal bouncing",1,"It ain't an echo, he got the pauses wrong",3,"Meaning what?",1,"Meaning he put the breath in a different place than I put it - that's all I can tell you"}},
{"s12_bell_hum_follows_024","any",2,"reg=worker,civilian|tmp=seasoned|mood=fear|world=vehicle",{1,"Every time I moved the truck that hum come with me - took me four stops to say it out loud",2,"Alternator whine",1,"I killed the engine, Earl - four times, key out and everything"}},
{"s12_bell_kids_singing_025","any",2,"reg=civilian,family|tmp=seasoned|hour=22,4|mood=grim",{1,"I ain't going to sit here and tell you I heard children - I'm going to say I heard high voices",2,"That's the same thing",1,"It ain't, and I'd appreciate it if you'd let me have the difference"}},
{"s12_bell_truck_no_engine_026","any",2,"reg=law,law|tmp=seasoned,veteran|hour=1,5|mood=calm|world=vehicle",{1,"Gravel noise on the drive about three, tires on gravel, clear as anything",2,"Engine?",1,"No engine, somebody pushed a vehicle up our drive in the dark and pushed it back out again"}},
{"s12_bell_bell_for_us_027","any",2,"reg=civilian,family|tmp=seasoned|hour=20,2|mood=grim",{1,"One ring, come in... two, trouble... three, run like hell, remember?",2,"I remember, we agreed that in June",1,"Somebody out there rang it three times last night and it wasn't any of us that rang it"}},
{"s12_bell_the_saw_stops_028","any",2,"reg=worker,civilian|tmp=seasoned|hour=19,0|mood=fear",{1,"That saw south of us quit this morning",2,"Well, good, you been on about it a week",1,"I know I have, now I want it back on, and I don't much care for what that says about me"}},
{"s12_bell_jukebox_029","any",2,"reg=outlaw,club,crime|tmp=predator,seasoned|hour=22,4|mood=grim|world=vehicle",{1,"Somebody's got a jukebox going in the tavern out on 31W - middle of the night",2,"Then let's go drink their beer",1,"Power's off on that whole stretch, light poles are down in the ditch - you still want to go?",2,"I'd like to see it",1,"Then you can see it, I'll wait with the truck and I'll leave at first light either way"}},
{"s12_bell_two_bells_030","any",2,"reg=civilian,rescue|tmp=seasoned|hour=5,9|mood=fear",{1,"There's two bells going now - Cedar Grove and something further off answering it",2,"Another church",1,"I've lived here fifty one years and I can name every church with a bell - there's one"}},
{"s12_bell_military_report_031","any",3,"reg=military,elite|tmp=veteran|hour=0,5|mood=calm",{1,"Bell, church type, eleven strikes, zero two forty, third night in a row, logging it as unknown",2,"Want a team on it?",1,"Negative, it draws them - whoever's pulling that rope knows it draws them",3,"So it's bait, Sergeant",1,"It's bait, which means somebody's set up where it drives them to, and that ain't the church"}},
{"s12_bell_kid_asks_032","any",2,"reg=family|tmp=fresh|hour=21,2|mood=sad",{1,"She asked me why the church bell rings at night now",2,"What'd you tell her?",1,"I said some folks lost their watch and they're guessing - she took that - she's six"}},
{"s12_bell_hedge_then_commit_033","any",2,"reg=civilian,worker|tmp=seasoned|hour=23,4|mood=fear",{1,"Eight times it went - nine, I'd say nine",2,"Which is it?",1,"Nine, I counted on my fingers like a child and it was nine"}},
{"s12_bell_restart_sentence_034","any",2,"reg=civilian,family|tmp=fresh,seasoned|hour=22,3|mood=fear|world=door",{1,"We come out the back of the church, no, hold on, side door, 'cause the back was chained",2,"Alright, side door",1,"Side door, and the rope was still swinging - just a little, just enough that you'd notice it"}},
{"s12_bell_coda_rule_035","any",2,"reg=civilian,family,worker|tmp=seasoned|mood=grim",{1,"So that's why we don't answer the bell no more - not one of us, not for nothing",2,"And if it's folks needing help?",1,"Folks knock, we've been over it, folks come up the drive and knock"}},
{"s12_bell_apology_036","any",2,"reg=civilian,worker|tmp=seasoned|hour=1,5|mood=fear",{1,"Sorry, I know it's the middle of the night, I couldn't sit in there with it anymore",2,"Sit down, coffee's cold but it's coffee",1,"It's gone to ringing between the hours now, twenty after, ten till - no pattern I can find"}},
{"s12_bell_downgrade_037","any",2,"reg=civilian,family|tmp=seasoned|hour=21,3|mood=fear|world=building",{1,"It's probably a cow got in that churchyard and leaned on the rope",2,"A cow",1,"A cow, eleven times, real even, at two in the morning - anyway, I moved the kids downstairs"}},
{"s12_bell_veteran_flat_038","any",2,"reg=military,elite|tmp=veteran|hour=0,4|mood=calm",{1,"Bell again",2,"Heard it",1,"Ain't our problem tonight, wake me at four",2,"Roger"}},
{"s12_bell_predator_joke_039","any",2,"reg=raider,gang,prison|tmp=predator|hour=22,4|mood=funny",{1,"Bell's going again, somebody in this county's got religion real bad",2,"Or somebody's herding",1,"Herding - yeah, whoever it is can have the county, I ain't arguing with a man who rings a bell"}},
{"s12_bell_worker_fix_040","any",2,"reg=worker|tmp=seasoned|mood=grim",{1,"I hung that bell wheel in eighty four, there's a pin in the yoke that has to be pulled to swing it",2,"So it can't ring on its own",1,"Not on its own, no, somebody's pulling a pin the size of your thumb every night in the dark"}},
{"s12_bell_says_a_name_041","any",3,"reg=civilian,family|tmp=fresh,seasoned|hour=23,4|mood=fear|world=building",{1,"There's a voice with the bell some nights, right after the last one, while it's still humming",2,"Saying what?",1,"A name",3,"Whose name?",1,"I'd as soon not say it in this room at night - ask me tomorrow in the daylight"}},
{"s12_bell_recorded_it_042","any",2,"reg=civilian,worker|tmp=seasoned|hour=21,2|mood=fear|world=window",{1,"I put a tape recorder in the window to catch it - cheap one, but it works",2,"Get it?",1,"Got the crickets, got the fan, got nothing at two forty - I heard it with my own ears at two forty"}},
{"s12_bell_trade_warning_043","any",2,"reg=civilian,worker|tmp=seasoned|mood=calm",{1,"If you're going through Cane Run, go in the morning and be out by four",2,"On account of the bell",1,"On account of what comes when it rings, the bell itself never hurt anybody that I know of"}},
{"s12_bell_swat_stack_044","any",2,"reg=swat,law|tmp=veteran|hour=0,5|mood=calm|world=stairs",{1,"We're not going in that steeple in the dark, anybody up there hears us on the stairs before we're halfway",2,"Daylight then",1,"Daylight, and we go up with a light and a long gun and we don't call out first"}},
{"s12_bell_the_gentleman_045","any",2,"reg=civilian,family|tmp=seasoned|hour=22,3|mood=fear",{1,"Around here we say the sexton, makes it easier to talk about at the table",2,"There's no sexton at Little Bethel",1,"There ain't, that's the joke and it's a poor one, but it's what we've got"}},
{"s12_bell_bell_at_funeral_046","any",2,"reg=rescue,family|tmp=seasoned|hour=10,15|mood=sad",{1,"We buried the Cobb boy at ten and that bell went right through the prayer - nine times",2,"He was nine",1,"He was nine, I have not told his mother that and I do not intend to"}},
{"s12_bell_i_went_up_047","any",3,"reg=civilian,worker|tmp=seasoned|hour=19,23|mood=grim|world=stairs",{1,"I went up them steeple stairs Thursday in the daylight - all the way up",2,"And?",1,"Bell's there - Rope's there, floor's got about an inch of pigeon mess on it, undisturbed",3,"So nobody's been up there",1,"Nobody's been up there, now you know exactly as much as I do and I'd like to talk about something else"}},
{"s12_bell_deserter_048","any",2,"reg=military|role=deserter|tmp=seasoned|hour=1,5|mood=grim|world=road",{1,"We heard that bell on the line every night and the LT wrote it up as civilian activity",2,"Was it?",1,"We walked to it once, church was shut and the road behind us was full when we turned around"}},
{"s12_bell_kid_counts_049","any",2,"reg=family|tmp=fresh|hour=21,1|mood=fear",{1,"The boy counts along with it now, out loud, under his breath, all the way to the end",2,"Tell him to quit",1,"I did, he says if somebody don't count it, nobody will know"}},
{"s12_bell_flat_close_050","any",2,"reg=civilian,worker|tmp=seasoned|hour=5,8|mood=calm",{1,"So it rang, and we sat up with the lamp off, and then it got light out",2,"And nothing came",1,"Nothing came, that's it, plain as that - I told it right, that's how it went"}},
{"s12_house_six_chairs_001","any",2,"reg=civilian,family|tmp=fresh,seasoned|hour=21,3|mood=fear|world=door,building",{1,"You know the Dees place? Brick one past the grain bins? I ain't going back in there",2,"Somebody living in it?",1,"No, that's the thing, every chair in that kitchen was set facing the back door - neat",2,"Kids messing around",1,"Six chairs, four of 'em belonged to that kitchen - so"}},
{"s12_house_pencil_days_002","any",2,"reg=worker,civilian|tmp=seasoned|hour=20,2|mood=grim|world=stairs,building",{1,"Got four steps up the stairs at the Kelso place and come right back down",2,"Stairs bad?",1,"Stairs are fine, somebody wrote the days on the wall in pencil - clean through to the twenty-ninth",2,"The twenty-ninth ain't happened",1,"No it has not"}},
{"s12_house_folded_carpet_003","any",3,"reg=law|tmp=seasoned,veteran|mood=grim|world=door,building",{1,"We cleared 114 Halbert, I'm putting front room clear and leaving it at that",2,"You'll have to put something for the rest of the house",1,"Back bedroom, the carpet was pulled up and folded - folded, Sarge",3,"Folded how?",1,"Like you'd fold a flag, corners and all, I shut that door and we come out"}},
{"s12_house_warm_bathwater_004","any",2,"reg=family|tmp=fresh|hour=22,4|mood=fear",{1,"I ain't going in the Rollins house again, Mama - send Lonnie",2,"You told me it was empty",1,"It is empty, the tub was run full and the water was warm",2,"Then somebody's in there with you",1,"I hollered - twice, then I quit hollering and come home"}},
{"s12_house_eleven_doors_005","any",2,"reg=military|tmp=veteran|mood=calm|world=door",{1,"We once searched a house on Tanner. I still wouldn't have slept there",2,"What put you off, Sergeant?",1,"All the interior doors were off the hinges and stacked in the hall - eleven of 'em",2,"That's enough to make me look for somewhere else too"}},
{"s12_house_broom_corner_006","any",2,"reg=raider,outlaw|tmp=predator,seasoned|mood=grim",{1,"We ain't hitting that white house on Piney Fork again",2,"You scared of a house now?",1,"I'm careful about whoever swept it, little pile of glass in the corner, broom stood up next to it",2,"And?",1,"Somebody's keeping house in there - go on by yourself if it's bothering you"}},
{"s12_house_towel_on_nail_007","any",2,"reg=civilian,worker|tmp=seasoned|hour=19,23|mood=fear|world=vehicle",{1,"Barn behind the Kelso place is rot and flies and about two hundred degrees",2,"So don't sleep in the barn",1,"There's a white dish towel hung on a nail in there - folded over twice - dry",2,"Huh",1,"Yeah, huh, I went and slept in the truck"}},
{"s12_house_four_plates_008","any",2,"reg=family,civilian|tmp=fresh,seasoned|hour=20,1|mood=grim",{1,"Supper was still set out at the Wickham house - four plates",2,"Well, folks left in a hurry, that's all over the county",1,"Three chairs, Wanda, I keep coming back around to the chairs"}},
}
